<?php $__env->startSection('title', 'Audit trail'); ?>
<?php $__env->startSection('content'); ?>
<div class="page-heading"><div><h1>Audit trail</h1><p>Every change made in the system, who made it and when. Entries cannot be edited or deleted; run <code>php artisan audit:verify</code> to check the chain.</p></div></div>
<div class="panel"><div class="panel-body"><form method="GET" style="display:flex;gap:10px;flex-wrap:wrap">
<select name="entity_type"><option value="">All records</option><?php $__currentLoopData = $types; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $t): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('entity_type')===$t): echo 'selected'; endif; ?>><?php echo e($t); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select>
<select name="action"><option value="">All actions</option><?php $__currentLoopData = ['CREATED','UPDATED','DELETED']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $a): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('action')===$a): echo 'selected'; endif; ?>><?php echo e($a); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select>
<input name="q" value="<?php echo e(request('q')); ?>" placeholder="Record number or name"><input name="user" value="<?php echo e(request('user')); ?>" placeholder="User">
<input type="date" name="from" value="<?php echo e(request('from')); ?>"><input type="date" name="to" value="<?php echo e(request('to')); ?>"><button class="btn">Filter</button></form></div></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Record</th><th>Changes</th></tr></thead><tbody>
<?php $__empty_1 = true; $__currentLoopData = $entries; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $e): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($e->occurred_at->setTimezone(config('app.timezone'))->format('d M Y H:i:s')); ?></td><td><?php echo e($e->user_name ?? '—'); ?><div class="muted small"><?php echo e($e->ip_address); ?></div></td><td><?php echo e($e->action); ?></td>
<td><?php echo e($e->entity_type); ?><div class="small"><?php echo e($e->entity_label); ?></div></td><td><?php echo $__env->make('audit._changes', ['entry' => $e], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></td></tr>
<?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5" class="muted">No entries match.</td></tr><?php endif; ?></tbody></table></div><div class="panel-body"><?php echo e($entries->links()); ?></div></div>
